import { CatalogSchema } from './schema.js';
import type { Catalog } from './types.js';

/** The catalog committed in snapshot.json, generated by `npm run catalog:refresh`. */
export async function bundledSnapshot(): Promise<Catalog> {
  const module = await import('./snapshot.json', { with: { type: 'json' } });
  return CatalogSchema.parse(module.default);
}

/** Drops variants that carry neither an intelligence score nor a cost, which nothing can rank. */
export function toSnapshot(catalog: Catalog): Catalog {
  return {
    ...catalog,
    variants: catalog.variants.filter((v) => v.intelligence !== undefined || v.costPerTask !== undefined),
  };
}
